#include<bits/stdc++.h>
using namespace std;using V=vector<int>;using B=__uint128_t;int pc[2048];B full=(B(1)<<72)-1;long long graphs,ad,ed,tests,one,two,thr,ob,peak=0;int cno,cm;string pre;mt19937 rng(821);
struct C{int w;B must,avoid;};
int cnt(B a){return __builtin_popcountll((uint64_t)a)+__builtin_popcountll((uint64_t)(a>>64));}
int pos(B a){if((uint64_t)a)return __builtin_ctzll((uint64_t)a);return 64+__builtin_ctzll((uint64_t)(a>>64));}
void greedy(V a, V b,int i,int j,V t){ofstream f(pre+".signedwin");f<<cno<<' '<<cm<<' '<<i<<' '<<j<<"\n";for(int k:a)f<<k<<" ";f<<"\n";for(int k:b)f<<k<<" ";f<<"\n";for(int k:t)f<<k<<" ";f<<endl;cout<<"SUCCESS signed support "<<i<<" versus "<<j<<endl;exit(0);}
int main(int ac,char**av){pre=av[1];int seconds=atoi(av[2]);auto start=chrono::steady_clock::now();auto tm=[&](){return chrono::duration<double>(chrono::steady_clock::now()-start).count();};for(int i=0;i<2048;i++)pc[i]=__builtin_popcount(i);ifstream f(pre+".codes");int n,l;f>>n>>l;V CODES[96];for(V&v:CODES){int s,x;f>>s;while(s--){f>>x;v.push_back(x);}}
V masks;for(int m=1;m<2048;m++)if(pc[m]==4||pc[m]==8)masks.push_back(m);vector<pair<int,int>> jobs;for(int k=0;k<96;k++)for(int m:masks)jobs.push_back({k,m});shuffle(jobs.begin(),jobs.end(),rng);for(auto [kk,m]:jobs){if(tm()>seconds)break;cno=kk;cm=m;V a=CODES[kk];int nf=pc[m]/4, other=2047^m;B d0[2048]{},d1[2048]{},adj[72];for(int w=0;w<2048;w++){B bits=0;for(int i=0;i<72;i++)if(pc[a[i]^w]<4)bits|=B(1)<<i;d0[w]=bits;}for(int w=other;;w=(w-1)&other){B bits=0;for(int i=0;i<72;i++)if(pc[(a[i]^w)&other]+nf<4)bits|=B(1)<<i;d1[w]=bits;if(!w)break;}for(int i=0;i<72;i++)adj[i]=d1[a[i]&other];vector<C> u;vector<V> min1(72);for(int w=0;w<2048;w++){if(find(a.begin(),a.end(),w)!=a.end())continue;B s=d0[w],t=d1[w&other],z=s&t;int c=cnt(z);if(c<=1){int k=u.size();u.push_back({w,s,t});if(c==1)min1[pos(z)].push_back(k);}}graphs++;
for(int rem=-1;rem<72;rem++){B kept=full;if(rem>=0)kept^=B(1)<<rem;int minneed=1+(rem>=0);B left=kept;vector<B> comps;while(left){B part=left&-left,front=part;left^=part;while(front){B newfront=0;while(front){int k=pos(front);front&=front-1;newfront|=adj[k];}newfront&=left;left^=newfront;part|=newfront;front=newfront;}comps.push_back(part);}int kcomp=comps.size();assert(kcomp<=70);vector<C> elig;for(auto x:u){tests++;if(x.must&x.avoid&kept)continue;B s=0,t=0;for(int g=0;g<kcomp;g++){if(x.must&comps[g])s|=B(1)<<g;if(x.avoid&comps[g])t|=B(1)<<g;}if(s&t)continue;elig.push_back({x.w,s,t});}if(rem<0)one+=elig.size();if(rem>=0)two+=elig.size();if((int)elig.size()<minneed)continue;
for(int i=0;i<(int)elig.size();i++)for(int j=rem<0?i:i+1;j<(int)elig.size();j++){auto x=elig[i],y=elig[j];bool same=!(x.must&y.avoid)&&!(y.must&x.avoid)&&((i==j)||pc[x.w^y.w]>=4);bool opp=!(x.must&y.must)&&!(x.avoid&y.avoid)&&pc[(x.w^y.w)&other]+nf>=4;if(!same&&!opp)continue;bool xy=!same;B flips=x.must|(xy?y.avoid:y.must);V labels,uv;for(int h=0;h<72;h++)if(h!=rem){int g=0;while(!(comps[g]>>h&1))g++;labels.push_back((flips>>g)&1);uv.push_back(a[h]);}labels.push_back(0);uv.push_back(x.w);if(i!=j){uv.push_back(y.w);labels.push_back(xy);}for(int k=0;k<(int)uv.size();k++)for(int b=0;b<k;b++){int dx=uv[k]^uv[b],dist=labels[k]==labels[b]?pc[dx]:nf+pc[dx&other];assert(dist>=4);}greedy(uv,labels,uv.size(),72,{});}}}cout<<"signed charts "<<graphs<<" eligible one "<<one<<" eligible after deletion "<<two<<" tests "<<tests<<" seconds "<<tm()<<endl;}